ui.css:
.panel{padding:8px 14px 8px 10px;border-radius:16px;background:radial-gradient(circle at 7px 7px,rgba(170,228,255,.55) 0 1.5px,transparent 2.2px),radial-gradient(circle at calc(100% - 7px) 7px,rgba(170,228,255,.55) 0 1.5px,transparent 2.2px),radial-gradient(circle at 7px calc(100% - 7px),rgba(170,228,255,.55) 0 1.5px,transparent 2.2px),radial-gradient(circle at calc(100% - 7px) calc(100% - 7px),rgba(170,228,255,.55) 0 1.5px,transparent 2.2px),linear-gradient(180deg,rgba(14,40,60,.86),rgba(4,14,26,.9));border:1px solid rgba(110,220,255,.38);box-shadow:0 0 0 3px rgba(8,22,34,.75),0 0 18px rgba(40,170,230,.22),inset 0 1px 0 rgba(255,255,255,.1);font:700 14px 'Exo 2',sans-serif;color:#ffe4f6}
.bar{position:relative;width:228px;height:14px;border-radius:999px;background:rgba(2,8,18,.92);border:1px solid rgba(255,140,220,.5);box-shadow:inset 0 2px 5px rgba(0,0,0,.8),0 0 10px rgba(255,90,200,.2);overflow:hidden}
.bar-fill{height:100%;border-radius:999px;background:linear-gradient(90deg,#b0207a,#ff6fd2 55%,#ffc8ee);box-shadow:0 0 12px rgba(255,111,210,.8)}
.bar::after{content:'';position:absolute;left:6px;right:6px;top:1px;height:40%;border-radius:999px;background:linear-gradient(180deg,rgba(255,255,255,.4),rgba(255,255,255,0))}
.tube-fill{border-radius:999px;background:radial-gradient(circle at 30% 50%,rgba(255,255,255,.75) 0 1.3px,transparent 1.8px) 0 0/20px 100% repeat-x,linear-gradient(90deg,#13708f,#34f0c8 62%,#c8fff2);box-shadow:0 0 10px rgba(52,240,200,.75)}
.sonar{position:relative;width:112px;height:112px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:repeating-radial-gradient(circle,transparent 0 12px,rgba(90,232,255,.16) 12px 13px),radial-gradient(circle,rgba(10,46,66,.92),rgba(3,12,24,.94) 70%);border:2px solid rgba(110,225,255,.6);box-shadow:0 0 0 5px rgba(10,26,40,.9),0 0 0 6px rgba(120,230,255,.32),0 0 26px rgba(60,210,255,.3),inset 0 0 18px rgba(0,0,0,.85)}
.sonar::before{content:'';position:absolute;inset:2px;border-radius:50%;background:conic-gradient(from 0deg,rgba(52,240,200,0) 0deg 280deg,rgba(52,240,200,.32) 352deg,rgba(210,255,245,.8) 360deg);animation:sweep 4.5s linear infinite}
@keyframes sweep{to{transform:rotate(360deg)}}
.card{border-radius:26px;background:linear-gradient(180deg,rgba(10,34,52,.93),rgba(3,11,22,.96));border:1px solid rgba(120,232,255,.5);box-shadow:0 0 0 5px rgba(10,26,40,.92),0 0 0 6px rgba(120,232,255,.22),0 0 26px rgba(60,210,255,.22)}
.porthole{width:104px;height:104px;border-radius:50%;background:radial-gradient(circle at 50% 45%,rgba(30,90,120,.55),rgba(3,12,24,.95) 70%);border:4px solid #1d3a50;box-shadow:0 0 0 1px rgba(150,240,255,.6),0 0 16px rgba(80,220,255,.35),inset 0 0 14px rgba(0,0,0,.8)}
